allow:
Bash(powershell -Command "\(Invoke-WebRequest -Uri 'https://devapi02.awfatech.com/attendance/openapi.json' -UseBasicParsing -TimeoutSec 30\).Content" 2>/dev/null | node -e "
let d='';process.stdin.on\('data',c=>d+=c\);process.stdin.on\('end',\(\)=>{
const s=JSON.parse\(d\);
const p=s.paths['/api/v2/attendance/{app}/{user}/admin/attendance-list'];
if\(p&&p.get\){
  const g=p.get;
  console.log\('=== PARAMS ==='\);
  \(g.parameters||[]\).forEach\(p=>console.log\(JSON.stringify\(p\)\)\);
  console.log\('=== RESPONSES ==='\);
  const r200=g.responses?.['200'];
  if\(r200\){
    const schema=r200.content?.['application/json']?.schema;
    if\(schema\){
      // resolve refs
      const resolve=\(ref\)=>{const parts=ref.split\('/'\);let o=s;for\(const p of parts.slice\(1\)\)o=o[p];return o;};
      const expand=\(obj,depth=0\)=>{
        if\(!obj||depth>4\)return obj;
        if\(obj['$ref']\)return expand\(resolve\(obj['$ref']\),depth+1\);
        if\(obj.properties\){
          const r={};for\(const[k,v] of Object.entries\(obj.properties\)\)r[k]=expand\(v,depth+1\);
          return {type:obj.type,required:obj.required,properties:r};
        }
        if\(obj.items\)return{type:'array',items:expand\(obj.items,depth+1\)};
        if\(obj.allOf\)return expand\(obj.allOf[0],depth+1\);
        return obj;
      };
      console.log\(JSON.stringify\(expand\(schema\),null,2\)\);
    }
  }
}else{console.log\('NOT FOUND'\);}
}\);" 2>/dev/null)
